// 1. MODIFY VALIDATION NODE - Only require email
const req = $input.first().json;

// For email subscription, only email is required
if (!req.email?.trim()) {
  return [{json: {...req, error: "Email is required"}}];
}

return [{
  json: {
    email: req.email.toLowerCase().trim(),
    source: 'website_subscription',
    ts: new Date().toISOString(),
    // Optional fields that might come from form
    name: req.name?.trim() || '', 
    interest: req.interest || 'newsletter' // personal branding, LinkedIn help, etc.
  }
}];

